$string['settings:embed_dimensions_desc'] = 'רוחב ווקטור ה-embedding, שחייב להיות רוחב שהמודל אכן מציע. OpenAI text-embedding-3-small: 1536. nomic-embed-text: 768. מודלי Voyage מקבלים 256, 512, 1024 ו-2048 (הרוחב המקורי 1024 מושמט מן הבקשה); רוחב לא תקין מושמט במקום להישלח, כך שהייתם מקבלים בשקט את הרוחב המקורי במקום זה שביקשתם. voyage-4-large ברוחב 2048 היא התצורה הנמדדת — שיפור של 14.0 נקודות אחוז בהיזכרות על שאילתות מציאותיות, בפחות מ-4 דולר לחודש — ואימוצה דורש אינדוקס מלא מחדש, כי המאחזר מסרב לנקד שאילתה מול קטעים ממרחב embedding אחר. השתמשו בהעברת מודל ה-embedding שבדף אינדקס ה-RAG במקום לשנות קודם את הערך הזה.';
