// v4.4.0: course-page CSP setting.
$string['settings:csp_course_pages_mode'] = 'Content-Security-Policy בדפי קורס';
$string['settings:csp_course_pages_mode_desc'] = 'כותרת CSP אופציונלית בדפי קורס שבהם ווידג\'ט עוזר הקורס AI פעיל. <strong>כבוי</strong>: ללא כותרת (ברירת מחדל). <strong>דיווח בלבד</strong>: שליחת <code>Content-Security-Policy-Report-Only</code> — הדפדפנים מתעדים הפרות אך אינם חוסמים. שימושי לתקופת תצפית של שבוע. <strong>אכיפה</strong>: שליחת <code>Content-Security-Policy</code> — הדפדפנים חוסמים מקורות iframe, שליפות וטעינות מסוכנות אחרות שאינן ברשימת ההיתר. מסייע לצמצם את ההשפעה של סקריפטים שרירותיים שהודבקו בהגדרת האתר Additional HTML (אירוע IBL AI / Raison מ-29 באפריל 2026). אינו משפיע על נקודות הקצה של [[tutorshort]], ששולחות תמיד CSP מחמירה יותר.';
$string['settings:csp_mode_off'] = 'כבוי (ללא כותרת בדפי קורס)';
$string['settings:csp_mode_report_only'] = 'דיווח בלבד (תיעוד הפרות, ללא חסימה)';
$string['settings:csp_mode_enforce'] = 'אכיפה (חסימת טעינות שאינן ברשימת ההיתר)';
// v4.5.0: site-wide pedagogy defaults.
$string['settings:pedagogy_defaults_heading'] = 'ברירות מחדל פדגוגיות';
$string['settings:pedagogy_defaults_heading_desc'] = 'מצב ברירת המחדל לכל האתר עבור כל תכונה פדגוגית. הפעילו כאן תכונה וכל קורס יירש אותה, אלא אם לאותו קורס יש עקיפה מפורשת בדף הגדרות הקורס של [[tutorshort]] (אילוץ הפעלה / אילוץ כיבוי). בשדרוג לגרסה v4.5.0, כל עקיפת "אילוץ כיבוי" ברמת קורס שהוגדרה לערך ברירת המחדל הישן <code>0</code> מנוקה, כדי שברירות המחדל הגלובליות החדשות ייכנסו לתוקף בצורה נקייה. ברירת מחדל: כבוי — שדרוגים מגרסה v4.4.x אינם משנים דבר עד שמנהל מפעיל תכונה.';
