// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = 'נתוני ספקים ועלויות';
$string['settings:vendor_data_heading_desc'] = 'בקרות לדף הניהול האופציונלי של סטטוס DPA של ספקים, ולעורכי העקיפות המאפשרים למנהלים לשמור על עדכניות טבלת הספקים המצורפת וכרטיס תעריפי ה-LLM ללא שינוי בקוד. שני עורכי העקיפות הם JSON; ערך ריק חוזר לברירות המחדל הקשיחות המצורפות לתוסף.';
$string['settings:vendor_dpa_admin_page_enabled'] = 'הצגת דף הניהול של DPA ספקים';
$string['settings:vendor_dpa_admin_page_enabled_desc'] = 'כאשר מופעל, "Vendor DPA Status" מופיע תחת ניהול האתר → תוספים → תוספים מקומיים → AI Course Assistant. הדף מציג את טבלת הספקים ממוזגת עם העקיפה שלהלן. ברירת מחדל: כבוי — רוב המנהלים אינם זקוקים למשטח זה.';
$string['settings:vendor_dpa_overrides'] = 'עקיפות DPA של ספקים (JSON)';
$string['settings:vendor_dpa_overrides_desc'] = 'JSON object keyed by vendor id. Each value is an object whose fields override the hardcoded vendor row. Fields you do not specify fall through to the default. A new vendor key in the override is added to the table; edits apply per field. Malformed JSON is ignored at runtime — fix the parse error here when the saved value does not appear in the Vendor DPA page.';
$string['settings:rate_card_overrides'] = 'עקיפות של כרטיס תעריפי LLM (JSON)';
$string['settings:rate_card_overrides_desc'] = 'אובייקט JSON שמפתחו הוא תחילית שם המודל. כל ערך הוא <code>{"input": float, "output": float}</code> ב-USD לכל 1,000,000 טוקנים. מחליף את רשומת לוח התעריפים המצורפת עבור אותה תחילית. לדוגמה: <pre>{ "gpt-4o-mini": { "input": 0.15, "output": 0.60 }, "claude-sonnet-4.6": { "input": 3.00, "output": 15.00 } }</pre> לקריאה בלבד מגרסה 7.4.0: השדה הזה עדיין ממוזג (מעל הבסיס המצורף לקוד, מתחת למרשם המודלים) כך שדריסה קיימת ממשיכה לעבוד, אבל שום דבר אינו כותב אליו עוד ומחירים חדשים שייכים למרשם המודלים, שרושם מי קבע כל מחיר ומתי. הרענון השבועי נהג לדרוס את כל השדה הזה, ובכך השמיד כל מחיר שהוזן ביד בהרצה הבאה.';

// v4.7.0: rate-card auto-refresh.
$string['settings:rate_card_auto_refresh'] = 'רענון אוטומטי ממקור עליון';
