$string['settings:avatar_rate_card_overrides'] = 'עקיפות של כרטיס תעריפי אוואטר (JSON)';
$string['settings:avatar_rate_card_overrides_desc'] = 'אובייקט JSON הממופתח לפי ספק אוואטר, עם תעריף יחיד בדולר לדקה. מחליף את התעריף המצורף עבור אותו ספק. דוגמה: <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> ריק = שימוש בברירות המחדל המצורפות של גרסה v4.10.0: D-ID 0.30 דולר לדקה, HeyGen 0.50 דולר לדקה, Tavus 0.30 דולר לדקה, Synthesia 0.40 דולר לדקה. הגדירו כאן את התעריף החוזי שלכם כדי שלוח ניתוח הנתונים ישקף את העלות בפועל של המוסד.';
$string['settings:talking_avatar_did_webhook_secret'] = 'סוד חתימה ל-webhook של D-ID';
$string['settings:talking_avatar_did_webhook_secret_desc'] = 'אופציונלי. כאשר מוגדר, D-ID יכול לשלוח בבקשת POST אירועי סיום סשן אל <code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code>, חתומים בסוד זה בכותרת <code>X-DID-Signature</code> (HMAC-SHA256 הקסדצימלי). שורות שמגיעות מה-webhook גוברות על פעימת הלב של צד הלקוח. ריק = המטפל כבוי, ופעימת הלב יחד עם משימת הניקוי השעתית מטפלות בסיום הסשן באופן בלעדי.';
$string['settings:talking_avatar_heygen_webhook_secret'] = 'סוד חתימה ל-webhook של HeyGen';
$string['settings:talking_avatar_heygen_webhook_secret_desc'] = 'אופציונלי. כאשר מוגדר, HeyGen יכול לשלוח בבקשת POST אירועי סיום סשן חתומים בסוד זה בכותרת <code>X-HeyGen-Signature</code> (HMAC-SHA256 הקסדצימלי). ריק = המטפל כבוי.';
$string['settings:talking_avatar_tavus_webhook_secret'] = 'סוד חתימה ל-webhook של Tavus';
$string['settings:talking_avatar_tavus_webhook_secret_desc'] = 'אופציונלי. כאשר מוגדר, Tavus יכולה לשלוח בבקשת POST אירועי סיום שיחה חתומים בסוד זה בכותרת <code>X-Tavus-Signature</code> (HMAC-SHA256 הקסדצימלי). ריק = המטפל כבוי.';
$string['settings:talking_avatar_synthesia_webhook_secret'] = 'סוד חתימה ל-webhook של Synthesia';
$string['settings:talking_avatar_synthesia_webhook_secret_desc'] = 'אופציונלי. כאשר מוגדר, Synthesia יכולה לשלוח בבקשת POST אירועי סיום סשן של סוכן, חתומים בסוד זה בכותרת <code>X-Synthesia-Signature</code> (HMAC-SHA256 הקסדצימלי). ריק = המטפל כבוי.';
