$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'פרומפט מפורט למצב סוקרטי';
$string['settings:socratic_verbose_desc'] = 'כאשר מופעל, קורסים במצב סוקרטי מקבלים את הנחיית העשה/אל תעשה המלאה בת כ-600 טוקנים שנוספה במקור בגרסה v3.9.30. כאשר כבוי (ברירת מחדל), הם מקבלים הנחיה בת שורה אחת שמודלים מתארחים מודרניים מצייתים לה באופן אמין, והיא חוסכת כ-600 טוקנים בכל תור. הפעילו זאת אם קורס פועל על מודל חלש יותר המתארח עצמית וזקוק לפיגומים המפורשים.';
$string['settings:prompt_budget_chars'] = 'תקציב תווים לפרומפט המערכת';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'תקרת תוכן העמוד הנוכחי (תווים)';
$string['settings:current_page_content_maxchars_desc'] = 'מספר התווים המרבי של טקסט העמוד הנוכחי המוזרק לפרומפט המערכת כמקטע "תוכן העמוד הנוכחי", כאשר RAG כבוי. ברירת המחדל 8,000 מבססת היטב שאלות ספציפיות לעמוד תוך השארת תקציב למבנה ולהוראות. (כאשר RAG מופעל, העמוד מבוסס במקום זאת על הקטעים הרלוונטיים ביותר שלו, בהטיה לעמוד הנוכחי, ולכן מגבלה זו אינה חלה.) עמוד ארוך מאוד נחתך מההתחלה למספר תווים זה, כך שייתכן שסוף עמוד ארוך במיוחד לא יצוטט; הפעלת RAG מונעת זאת. אתרים מודעי עלות יכולים להגביל נמוך יותר (למשל 3,000-4,000). מוגבל לטווח 500-8,000. בלתי תלוי ב-<code>prompt_budget_chars</code>: זה מגביל רק את מקטע העמוד; התקציב מגביל את כל הפרומפט.';
$string['settings:prompt_verbosity'] = 'רמת פירוט הפרומפט';
$string['settings:prompt_verbosity_desc'] = 'רמת הפירוט שהיא ברירת המחדל לבלוקי ההוראות (מצב סוקרטי, משאבים חיצוניים). תמציתי (ברירת מחדל) הוא מה שמודלים מתארחים מודרניים מצייתים לו באופן אמין; רגיל מוסיף פיגומים מפורשים למודלים בדרג הביניים; מפורט משמר את ההנחיות הכבדות מתקופת v3.9.30 עבור מודלים חלשים יותר המתארחים עצמית. עקיפה ברמת הקורס זמינה באמצעות <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'תמציתי (מומלץ למודלים מתארחים)';
$string['settings:prompt_verbosity_standard'] = 'רגיל';
$string['settings:prompt_verbosity_verbose'] = 'מפורט (למודלים חלשים יותר המתארחים עצמית)';
$string['settings:prompt_metrics_enabled'] = 'איסוף מדדי פרומפט לפי מקטע';
$string['settings:prompt_metrics_enabled_desc'] = 'כאשר מופעל (ברירת מחדל), כל תור צ\'אט כותב שורת JSON אחת לכל פרומפט מורכב אל <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code>, עם ספירת תווים לפי קטגוריה. נשמרים 7 הימים האחרונים. דף מדדי הניהול מצרף אותם לצורך המלצת התקציב. לא נרשם מידע מזהה אישי — רק גדלי מקטעים. כבו זאת אם המוסד שלכם מעדיף שלא יהיה קובץ מדדים כלל.';
$string['settings:prompt_budget_auto_tune'] = 'כיול יומי אוטומטי של תקציב הנחיית המערכת (מיושן)';
$string['settings:prompt_budget_auto_tune_desc'] = 'מיושן. אינו עושה דבר אלא אם מצב התקציב שלמעלה מוגדר כ<strong>קבוע</strong>. משימה יומית הסיקה את תקציב התווים על ידי מעקב אחר קטיעות ורדיפה אחר ההנחיה הגדולה ביותר שראתה. גזירת התקציב מחלון ההקשר של המודל עושה זאת טוב יותר: היא אינה מתנדנדת ואינה זקוקה לנתוני התחלה. השניים גם התנגשו, כי המשימה כותבת את תקציב התווים, וכל ערך שאינו ברירת המחדל מבטל את התקציב הנגזר. השאירו זאת כבוי; יוסר בגרסה עתידית. ההמלצה עדיין מופיעה בעמוד <a href="/local/ai_course_assistant/prompt_metrics.php">מדדי הנחיה</a>.';
$string['task:auto_tune_prompt_budget'] = 'כיול אוטומטי של תקציב ההנחיה של [[tutorshort]] לפי מדדים שנצפו';
$string['prompt_metrics:title'] = 'מדדי הנחיה + המלצת תקציב';
