$string['prompt_metrics:no_data'] = 'עדיין לא נרשמו מדדי הנחיה. שלחו כמה תורות צ\'אט מחשבון של לומד, ואז רעננו את העמוד הזה. (אם דגל לכידת המדדים כבוי בהגדרות התוסף, לא ייצברו נתונים.)';
