$string['task:milestone_check'] = 'שליחת אימיילי רפלקציה יומיים על אבני דרך (v5.3.0)';
$string['task:struggle_signal_review'] = 'סקירת אותות קושי אל תוך זיכרון הלומד הפרטי (v5.3.0)';
$string['empathy:title'] = 'תקשורת אמפתית וזיכרון המשכיות (v5.3.0)';
$string['empathy:desc'] = 'שלוש תכונות מתואמות שגורמות ל[[tutorshort]] להרגיש יותר כמו מאמן שמקשיב. המטרות לוכדות מדוע הלומד כאן. זיכרון ההמשכיות זוכר מה היה קשה בעבר, כדי ש[[tutorshort]] יוכל להציע זווית אחרת. אבני הדרך חוגגות רצפים והשלמות באמצעות אימייל. לכל תכונה יש מתג כיבוי עצמאי והצטרפות מרצון של הלומד. אותות קושי לעולם אינם יוצאים מהצ\'אט — לעולם לא נשלח אימייל על שיחה קשה.';
$string['empathy:outreach_master_enabled'] = 'מתג כיבוי ראשי לפניות';
$string['empathy:outreach_master_enabled_desc'] = 'כבוי כברירת מחדל בהתקנה חדשה. כאשר הוא כבוי, שום אימייל אמפתי מכל סוג שהוא אינו נשלח לעולם, ללא תלות במתגים לכל תכונה שלמטה. הפעילו אותו לאחר שבחנתם את ברירות המחדל לכל תכונה ואת תהליך ההסכמה של כל לומד.';
$string['empathy:goals_enabled'] = 'הפעלת שיחות על מטרות קריירה';
$string['empathy:goals_enabled_desc'] = 'מאפשר ללומדים למסור מיוזמתם שתי תשובות קצרות (מדוע הם כאן, למה הם רוצים להפוך) שמזינות את ההתאמה האישית. בצ\'אט בלבד; ללא אימיילים. בטוח להשאיר מופעל.';
$string['empathy:milestones_enabled'] = 'הפעלת אימיילי רפלקציה על אבני דרך';
$string['empathy:milestones_enabled_desc'] = 'שולח אימייל קצר וחם כאשר לומד מגיע לרצף של 7 ימים, לרצף של 30 ימים או להשלמת הקורס. דורש את מתג האב שלמעלה ובנוסף הסכמה של כל לומד. תקרה קשיחה של אימייל אחד לכל לומד בכל 7 ימים, בכל הערוצים יחד.';
$string['empathy:memory_enabled'] = 'הפעלת זיכרון המשכיות להתאמה אישית';
