$string['pedagogy:crossmastery_desc'] = 'כאשר האפשרות מופעלת, [[tutorshort]] מזהה מתי לומד כבר השיג שליטה ביעד בקורס אחר (בהתאמה לפי מזהה כשירות או כותרת) ומכיר בכשירות הקודמת הזו במקום לתרגל אותה מחדש. דורש מעקב שליטה; קורסים ללא יעדים יחזרו להתנהגות ברירת המחדל באופן חלק. למטרות ייעוץ בלבד — לעולם אינו משנה את ציון השליטה השמור של הלומד באף קורס.';
