// Forward learning-path awareness (v5.8.0).
$string['pedagogy:program_path'] = 'מודעות למסלול הלמידה קדימה מופעלת כברירת מחדל';
$string['pedagogy:program_path_desc'] = 'כאשר מופעל, [[tutorshort]] יכולה לומר ללומד לאן מוביל הקורס הנוכחי בהמשך התוכנית שלו (תואר או תעודה) וכיצד המושגים של היום מקשרים לקורסים מאוחרים יותר. קוראת את תוסף Programs של Moodle (Degrees ו-Learn) ונוקבת בשם של קורס הבא ספציפי רק היכן שהתוכנית מגדירה דרישת קדם או סדר נדרש; אחרת היא מציינת את מיקומו של הלומד במסלול. ייעוצי בלבד — היא לעולם אינה משנה הרשמה או שליטה, ומשתמשת אך ורק בהקצאת התוכנית של הלומד הנוכחי עצמו. אינה עושה דבר בשקט היכן שאף תוכנית אינה חלה.';

