$string['settings:backend_context_tokens'] = 'חלון ההקשר של ה-backend (טוקנים)';
$string['settings:backend_context_tokens_desc'] = 'אורך ההקשר המרבי (max_model_len) של ה-backend של ה-AI שלך, בטוקנים. הגדר ל-0 עבור מודלים מתארחים בעלי חלון גדול (ללא הגבלה). כאשר מוגדר מעל 0 (לדוגמה 8192 ב-backend vLLM באירוח עצמי), [[tutorshort]] מצמצמת את תקציב התווים של הנחיית המערכת שלמעלה כך שההנחיה יחד עם הפלט השמור והיסטוריית השיחה ייכנסו לחלון, אפילו בשפות צפופות בטוקנים. עיין בדף הוויקי Deployment Sizing כדי לראות כיצד זה ממופה למשתמשים בו-זמניים.';
