$string['settings:rag_min_similarity'] = 'רלוונטיות מינימלית (קוסינוס)';
$string['settings:rag_min_similarity_desc'] = 'מסנן קטעים שאוחזרו שדמיון הקוסינוס שלהם לשאלה נמוך מערך זה, כך ששאלה לא רלוונטית או דלילה תזריק פחות קטעים (או אפס) במקום למלא תמיד עד Top-K בהתאמות חלשות. טווח 0 עד 1; הערך 0 מנטרל את השער. הערך הנכון תלוי במודל ה-embedding: 0.25 מתאים ל-text-embedding-3-small. העלה אותו כדי להחמיר (פחות הקשר, יותר ממוקד בנושא), הורד אותו כדי להקל.';
$string['settings:rag_currentpage_boost'] = 'בונוס לעמוד הנוכחי';
$string['settings:rag_currentpage_boost_desc'] = 'בונוס קטן המתווסף לציון הרלוונטיות של קטעים מהעמוד שהלומד צופה בו כעת, כך ששאלות כמו "הסבר את זה" יעדיפו את העמוד הנראה כאשר הציונים קרובים. משפיע על הסדר בלבד: אין בכך כדי לאלץ קטע עמוד לא רלוונטי לעבור את שער הרלוונטיות המינימלית. הגדר 0 כדי לנטרל.';
$string['settings:history_mode'] = 'מצב בחירת היסטוריה';
$string['settings:history_mode_desc'] = 'כיצד נבחרים תורות שיחה קודמים לפני שליחתם למודל. <strong>סמנטי</strong> שומר רק את התורות האחרונים הרלוונטיים לשאלה הנוכחית (ותמיד את חילופי הדברים האחרונים), כך שתור קודם מיושן ולא רלוונטי לא ינפח את העלות ולא יסיט את התשובה מהמסלול; הוא מבצע קריאת embedding נוספת אחת לכל הודעה. <strong>עדכניות</strong> שומר את הזוגות האחרונים של "היסטוריית שיחה מרבית" ללא קשר לרלוונטיות (ההתנהגות הוותיקה, ללא קריאה נוספת). אם embedding אינו זמין, המצב הסמנטי חוזר אוטומטית לעדכניות.';
