$string['settings:history_semantic_minscore'] = 'סף רלוונטיות היסטוריה (קוסינוס)';
$string['settings:history_semantic_minscore_desc'] = 'במצב היסטוריה סמנטי, תור קודם נשמר רק אם הדמיון שלו לשאלה הנוכחית הוא לפחות ערך זה (חילופי הדברים האחרונים נשמרים תמיד). טווח 0 עד 1; תלוי מודל. העלה כדי להחמיר (פחות היסטוריה), הורד כדי לשמור יותר.';
