$string['settings:prompt_proportions_heading'] = 'פרופורציות חלקי ה-prompt (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'הקצה את תקציב ה-prompt של המערכת על פני ארבעה מכלים: אבטחה + זהות, מבנה קורס, תוכן קורס ועמוד נוכחי. המשקלות הן אחוזים שסכומם 100. ברירות המחדל המכווננות אמפירית (10 / 10 / 40 / 40) מגיעות מבנצ\'מרק כיוון המשקלות v5.6.0; השארת תיבת הטקסט ריקה משתמשת בברירות מחדל אלה. ה-boost האוטומטי מתאים את ההקצאה לכל תור בהתאם לכך שעמוד ספציפי נמצא בטווח.';
$string['settings:prompt_section_weights'] = 'משקלות חלק בסיסיים (JSON)';
$string['settings:prompt_section_weights_desc'] = 'אובייקט JSON אופציונלי הממפה כל מכל לאחוז. השאר ריק לשימוש בברירות המחדל של הבנצ\'מרק (10 / 10 / 40 / 40). דוגמה: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. המשקלות חייבות לסכום ל-100 (±5%). ל-<code>safety_identity</code> יש רצפה של 10% כדי שעמידות ל-jailbreak ומסמני פורמט פלט תמיד יגיעו במלואם. <code>current_page + course_content</code> חייב להיות לפחות 40% כדי שלמודל יהיה חומר מהותי לעגן בו. ערכים מחוץ לטווח חוזרים בשקט לברירות מחדל של הבנצ\'מרק; מנהלים צריכים לאמת על ידי בדיקת יומן ה-debug של ה-prompt לאחר שמירה.';
$string['settings:prompt_context_boost_mode'] = 'מצב boost הקשר';
$string['settings:prompt_context_boost_mode_desc'] = 'התאמה אוטומטית שמזיזה משקל לעבר חלק העמוד הנוכחי כאשר עמוד ספציפי בטווח, ולעבר תוכן הקורס כאשר לא נבחר עמוד. <strong>page_focus</strong> (ברירת מחדל) מזיז כ-15 נקודות משקל. <strong>aggressive</strong> מזיז 25 נקודות ועדיף כאשר לומדים שואלים באופן עקבי שאלות ספציפיות לעמוד. <strong>off</strong> משבית את ה-boost; משקלות הבסיס שנקבעו על ידי המנהל חלים בכל תור ללא קשר להקשר העמוד.';
$string['settings:prompt_context_boost_off'] = 'כבוי (השתמש במשקלות בסיס בכל תור)';
$string['settings:prompt_context_boost_page_focus'] = 'מיקוד עמוד (ברירת מחדל, הזזה של ~15 נקודות)';
$string['settings:prompt_context_boost_aggressive'] = 'אגרסיבי (~25 נקודות הזזה)';
$string['settings:prompt_section_weights_coach'] = 'עקיפת מצב מאמן (JSON, אופציונלי)';
$string['settings:prompt_section_weights_coach_desc'] = 'אובייקט JSON אופציונלי העוקף את משקלות החלק הבסיסיים ספציפית במצב מאמן של חידון מוערך (כאשר <code>quizmode=coach</code>). שימושי לאכיפת הקצאת <code>current_page</code> כבדה יותר בחידונים מבלי לשנות את הצ\'אט הרגיל. השאר ריק לירושת המשקלות הבסיסיות. אותן חוקי אימות כמו ההגדרה הבסיסית.';
$string['prompt_debug_view:title'] = 'צופה יומן debug של prompt';
$string['prompt_debug_view:subtitle'] = 'ה-prompt של המערכת שנורכב לפי תור + פירוט לפי חלק + היסטוריית שיחה + ההודעה הנוכחית של המשתמש + מטא-נתוני קובץ מצורף, בדיוק כפי שהמודל קיבל אותם. השתמש בזה לאמת האם חלק כמו תוכן עמוד נוכחי אכן נחת ב-prompt ולאבחן בעיות איכות תשובות מבלי להיכנס לשרת דרך SSH.';
$string['prompt_debug_view:disabled'] = 'רישום debug של prompt כרגע כבוי. לא ייכתבו רשומות חדשות עד שיופעל.';
$string['prompt_debug_view:enable_link'] = 'פתח את הגדרות הפלאגין כדי להפעיל "רשום prompt מערכת מורכב לקובץ".';
