$string['prompt_debug_view:show_more'] = 'הצג רשומות נוספות';
$string['settings:mastery_classifier_provider'] = 'ספק המסווג';
$string['settings:mastery_classifier_provider_desc'] = 'מזהה ספק המשמש למסווג שליטה לפי תור. השאר ריק לירושת ספק ה-AI ברירת המחדל. ברירת המחדל <code>openai</code> משולבת עם מודל המסווג <code>gpt-4o-mini</code> להלן — אפשרות TIER 1 הזולה ביותר לסיווג פלט מובנה (~$220/חודש חיסכון ב-100k MAU לעומת tier הצ\'אט). כאשר מוגדר, השורה בספקי השוואה עם מזהה ספק זה מספקת את מפתח ה-API, URL הבסיס והטמפרטורה.';
$string['settings:premium_escalation_heading'] = 'רמת הסלמה פרמיום (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'ניתוב אופציונלי לפי תור למודל פרמיום (Claude Opus 4.8 כברירת מחדל) עבור prompts שבהם tier הצ\'אט העיקרי מתקשה בבירור — בדרך כלל מתמטיקה רב-שלבית, CS ומדע. הוכרע על ידי bake-off A.10 מ-2026-06-09: Opus 4.8 זכה ב-14.97/15 לעומת 12.68/15 של gpt-4o ב-prompts קשים. שני נתיבי הפעלה: התאמות regex על הודעת המשתמש, או רשימת קורסים מאושרים שמסלימה כל תור. כבוי כברירת מחדל. ב-~5% הסלמה, צפה ל-~$700/חודש ב-100k [[unishort]] MAU מעל הוצאות הצ\'אט הבסיסיות.';
$string['settings:premium_escalation_enabled'] = 'הפעל ניתוב הסלמה פרמיום';
$string['settings:premium_escalation_enabled_desc'] = 'כאשר מופעל, הנתב לפי תור בודק את רשימת ה-regex להפעלה ואת רשימת הקורסים המאושרים לכל קריאת צ\'אט; תורות תואמים מנותבים לספק הפרמיום. נופל חזרה לספק העיקרי אם שורת הפרמיום חסרה או שלא ניתן ליצור מופע. עקיפות בוחר ה-LLM של המנהל תמיד גוברות ללא קשר.';
$string['settings:premium_escalation_provider'] = 'ספק פרמיום';
$string['settings:premium_escalation_provider_desc'] = 'מזהה ספק לניתוב קריאות פרמיום דרכו. חייב להתאים לשורה בספקי השוואה (כדי שמפתח ה-API, URL הבסיס והטמפרטורה יגיעו מאותו מקום שהמנהלים כבר מנהלים). ברירת מחדל <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'מודל פרמיום';
$string['settings:premium_escalation_model_desc'] = 'שם מודל המועבר לספק הפרמיום. ברירת מחדל <code>claude-sonnet-5</code> לפי פסיקת bake-off A.10.';
$string['settings:premium_escalation_triggers'] = 'regex של הפעלת פרמיום';
$string['settings:premium_escalation_triggers_desc'] = 'regex אחד של PCRE לשורה (ללא מפרידים; התאמה ללא תלות ברישיות מיושמת אוטומטית). שורות המתחילות ב-# הן תגובות. השאר ריק לשימוש בסט ברירת המחדל שנבחר מ-bake-off A.10 (סמני STEM רב-שלביים: "derive", "prove that", "step by step", LaTeX math, בלוקי קוד מגודרים, big-O, אינטגרלים, אופטימיזציה וכו\').';
$string['settings:premium_escalation_course_tags'] = 'רשימת קורסים מאושרים לפרמיום';
$string['settings:premium_escalation_course_tags_desc'] = 'שם קצר של קורס אחד או קידומת idnumber לשורה. כל תור בקורס תואם מוסלם אוטומטית ללא קשר ל-regex של ההודעה (השתמש עבור קורסים עתירי STEM שבהם הסלמה צריכה להיות ברירת המחדל). ההתאמה היא קידומת ללא תלות ברישיות — "MATH" תואם MATH121, MATH205 וכו\'.';
$string['settings:spend_cap_per_course_default'] = 'תקרת הוצאות ברירת מחדל לקורס (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'תקרה הגנתית המיושמת לכל קורס שאין לו תקרת הוצאות לקורס ספציפי מוגדרת. הגדר לדוגמה <code>30</code> כדי להגביל את ההוצאה החודשית של כל קורס יחיד ל-$30 מבלי לכוונן קורסים בודדים. <code>0</code> = ללא תקרת ברירת מחדל (רק תקרות ברמת האתר ועקיפות לפי קורס חלות). כאשר קורס חוצה 80% / 95% / 100% מתקרה זו, צינור ההתראות הקיים של spend-guard שולח את הודעת המנהל (רשימת נמענים: <code>spend_notify_emails</code>, חוזר למנהלי האתר). קורס ספציפי תמיד יכול להעלות את התקרה שלו על ידי הגדרת עקיפה לפי קורס גבוהה יותר.';
$string['settings:cost_anomaly_heading'] = 'גלאי חריגות עלויות (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'משימה מתוזמנת יומית (<code>cost_anomaly_check</code>) המשווה את הוצאות [[tutorshort]] של האתר של היום לחציון הגלגלי של 7 ימים. שולחת דוא"ל לרשימת נמענים <code>spend_notify_emails</code> (חוזר למנהלי האתר) כאשר היום עולה על המכפיל המוגדר × החציון. קולטת שלושה מצבי כשל שסף ה-80% / 95% / 100% של תקרת ההוצאות הקיימת מפספס: (1) קורס פרוע שבו התקרה המוחלטת לא נחצית אך קורס בודד מניב פתאום 10x מהנפח הרגיל שלו, (2) הפעלה מקרית של tier פרמיום, (3) ניתוב שגוי של ספק. כבוי כברירת מחדל; שקול [[tutorshort]]-פנימי של שאילתת Redash ב-<code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'הפעל גלאי חריגות עלויות';
$string['settings:cost_anomaly_enabled_desc'] = 'כאשר מופעל, המשימה המתוזמנת היומית מעריכה את הוצאות היום מול החציון הגלגלי של 7 ימים ושולחת דוא"ל למנהלים על חריגה. 7 הימים הראשונים לאחר ההפעלה מייצרים סטטוס <code>insufficient_history</code> (עדיין אין תקרת עזר היסטורית) ולא פולטים התראה. אידמפוטנטי ליום: דגל ב-<code>config_plugins</code> עוצר מיילים חוזרים אם cron רץ מספר פעמים.';
$string['settings:cost_anomaly_multiplier'] = 'מכפיל חריגה';
$string['settings:cost_anomaly_multiplier_desc'] = 'הוצאות היום חייבות לעלות על מכפיל זה × החציון ל-7 ימים כדי להפעיל התראה. ברירת מחדל <code>2.0</code>. הורד ל-<code>1.5</code> לאזהרות מוקדמות יותר (יותר פוזיטיביים שגויים בזמן גלי רישום). העלה ל-<code>3.0</code> אם השימוש של [[unishort]] מספיק לא יציב כדי שפיקים פי 2 יהיו שגרתיים.';
$string['task:cost_anomaly_check'] = 'בדיקת חריגות עלויות [[tutorshort]] (יומית)';
// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'חבילת מדיניות חתומה (עדכוני התנהגות מרחוק)';
$string['settings:policy_bundle_heading_desc'] = 'החל הגדרות התנהגות (הנחיות, ניתוב, טריגרים להסלמה, כיוונון RAG, מדיניות הוצאות) מקובץ JSON חתום קריפטוגרפית ללא פריסת קוד. משימה מתוזמנת יומית מאחזרת את ה-URL של החבילה, מאמתת את חתימת Ed25519 שלה מול המפתח הציבורי שלהלן, ומחילה את ההגדרות רק אם כל מפתח נמצא ברשימת ההיתרים המובנית וגרסת החבילה חדשה יותר מהאחרונה שהוחלה. מפתחות API, כתובות URL, webhooks והגדרות אבטחה לעולם אינם יכולים להיות מוגדרים על ידי חבילה. צרו וחתמו על חבילות באמצעות <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync).';
$string['settings:policy_bundle_enabled'] = 'הפעל סנכרון חבילת מדיניות';
$string['settings:policy_bundle_enabled_desc'] = 'כאשר מופעל, המשימה היומית מאחזרת ומחילה חבילות חתומות. כבוי כברירת מחדל. השבתה מפסיקה את כל הסנכרונים מיד; הגדרות שכבר הוחלו שומרות על ערכיהן.';
$string['settings:policy_bundle_url'] = 'URL של חבילת מדיניות';
$string['settings:policy_bundle_url_desc'] = 'כתובת HTTPS URL של ה-JSON של החבילה החתומה (לדוגמה אובייקט S3 או GitHub raw URL). ה-URL עובר את אותו אימות SSRF כמו נקודות קצה של ספקי AI; מארחים ברשת פרטית או plain-http זקוקים לרשומה ברשימת ההיתרים של נקודות קצה מהימנות של SSRF.';
$string['settings:policy_bundle_pubkey'] = 'מפתח ציבורי של חבילת מדיניות';
$string['settings:policy_bundle_pubkey_desc'] = 'מפתח ציבורי Base64 Ed25519 המשמש לאימות חתימות חבילה. צרו את זוג המפתחות באמצעות <code>policy_bundle_tool.php --keygen</code>; המפתח הפרטי נשאר אצל מחבר החבילה ואסור בהחלט להעלותו לשום מקום.';
$string['settings:policy_bundle_status'] = 'סנכרון אחרון';
$string['settings:policy_bundle_applied_version'] = 'גרסה מוחלת';
$string['task:policy_bundle_sync'] = 'סנכרון חבילת מדיניות חתומה של [[tutorshort]]';
$string['policy_bundle:invalid'] = 'חבילת המדיניות נדחתה: {$a}';
$string['prompt_debug_view:retrieved_chunks'] = 'מקטעים שאוחזרו (בחירת RAG)';
$string['prompt_debug_view:retrieved_chunks_hint'] = 'הקטעים שמנגנון האחזור בחר עבור שאלה זו, בסדר דירוג עם ציון הרלוונטיות והמקור שלהם (cmid). השתמשו בכך כדי לוודא שהמודל קיבל את תוכן הקורס התואם ביותר.';
$string['settings:avatar_animation_enabled'] = 'אנימציה של האווטאר';
$string['settings:avatar_animation_enabled_desc'] = 'מאייר את האווטאר SVG שנוצר: מצמוץ בסרק, בנוסף לתנועת פה מסונכרנת עם שמע המרת טקסט לדיבור בזמן שהעוזר מדבר. מכבד את העדפת התנועה המופחתת של מכשיר הלומד. עקיפה לפי קורס למדידת A/B: הגדר את ערך התצורה avatar_animation_course_COURSEID ל-0 או ל-1.';
$string['analytics:exp_heading'] = 'השוואת ניסוי A/B';
$string['analytics:exp_desc'] = 'השווה מעורבות בין שני קורסים על פני טווח הזמן שנבחר. נבנה לניסויים לפי קורס (לדוגמה בדיקת אנימציית האווטאר): שים את העקיפה בקורס אחד, השאר את האחר כבקרה, וקרא את ההבדל כאן.';
