$string['settings:bench_default_samples'] = 'Prompts להרצה';
$string['settings:bench_default_samples_desc'] = 'כמה prompts שולחת מדידה שהוכנסה לתור מן הדפדפן. כל prompt עולה שתי קריאות מודל אמיתיות — התשובה והשופט — ולכן זהו חוגת העלות. מוגבל ל-50 בקוד, וזה גם גודל מקבץ הזהב וגם מה ששומר הרצה אחת בתוך מגבלת הקצב של הספק.';
$string['settings:bench_heading'] = 'מדידות מודלים (benchmarks)';
$string['settings:bench_heading_desc'] = 'הרצת מדידה עונה על 50 prompts ומורה למודל שופט לנקד כל תשובה מול מחוון, ואחר כך שומרת שורה אחת: ממוצע המחוון, עלות לקריאה, וזמן עד הבייט הראשון. ההרצות מוכנסות לתור מדף מרשם המודלים ומורצות על ידי cron.';
$string['settings:bench_judge_model'] = 'מודל שופט';
$string['settings:bench_judge_model_desc'] = 'המודל שמנקד את התשובות. שינויו משנה את משמעותו של כל ציון שנלקח אחריו, ולכן כל הרצה רושמת את השופט שהשתמשה בו ואת גרסת התוסף שעליה רצה.';
$string['settings:bench_judge_provider'] = 'ספק השופט';
$string['settings:bench_judge_provider_desc'] = 'הספק של המודל שמנקד את התשובות. השאירו אותו מחוץ למקבץ המתמודדים: אסור למודל לתת ציון לעצמו.';
$string['settings:bench_min_quality_n'] = 'רף ההשוואה (פריטים שנוקדו)';
$string['settings:bench_min_quality_n_desc'] = 'המספר הקטן ביותר של פריטים מנוקדים שהרצה שמורה יכולה להחזיק ועדיין להיות מושווית להרצה אחרת. הרצות מתחת לרף נשמרות ומוצגות, מתויגות לעיון בלבד, כך שבדיקת עשן של שלושה prompts לא תוכל לעולם לעקוף תוצאה של חמישים prompts. השאירו על 0 כדי להשתמש בברירת המחדל המובנית; רף של 0 היה מבטל את ההגנה.';
$string['settings:embed_input_type_asymmetric'] = 'אסימטרי שאילתה/מסמך (מומלץ)';
$string['settings:embed_input_type_mode'] = 'סוג קלט ה-embedding';
$string['settings:embed_input_type_mode_desc'] = 'רק עבור אמבדינגים של Voyage. Voyage מטילה טקסט באופן שונה בהתאם לשאלה אם מדובר בשאילתה או במסמך. "אסימטרי" שולח input_type=query באחזור ו-input_type=document באינדוקס. זו כוונת הספק וזה מה שנמדד הכי טוב על הקורפוס הזה: שימוש בהטלת המסמך בצד השאילתה עלה 30.8 נקודות אחוז של recall והפסיד בכל טווח אורך שאילתה (2026-08-21, voyage-3.5, מערך בצורת ייצור). "מרחב משותף" שולח input_type=document בשני הצדדים; הוא מאחזר גרוע יותר באופן מדיד וקיים רק כביטוח למעבר, משום שהטלה אחת מאפשרת להחליף את מודל השאילתות בלי לחשב מחדש את האמבדינגים של הקורפוס. בחרו באסימטרי אלא אם אתם באמצע מעבר. השינוי אינו מחייב אינדוקס מחדש: משתנה רק ההטלה בצד השאילתה. זה אינו שידוך אסימטרי של מודלים (אינדוקס במודל Voyage גדול יותר מזה שבו אתם מבצעים שאילתות) — זו טכניקה אחרת שפעמיים לא שוחזרה על הקורפוס הזה, והיא נשלטת על ידי הגדרת מודל השאילתות, לא על ידי זו.';
$string['settings:embed_input_type_shared'] = 'מרחב משותף (ביטוח למעבר; מאחזר גרוע יותר)';
$string['settings:embed_migration_heading'] = 'העברת מודל ה-embedding';
$string['settings:embed_migration_heading_desc'] = 'שינוי מודל ה-embedding או רוחבו מבטל כל ווקטור מאוחסן: המאחזר מסרב לנקד שאילתה מול קטעים ממרחב embedding אחר, ולכן קורס אינו מאחזר דבר במקום לאחזר גרוע. ההגדרות האלה מתארות את המודל שאליו אתם עוברים. אחר כך הקורסים עוברים embedding מחדש אחד בכל פעם מדף אינדקס ה-RAG, והווקטורים החדשים נכתבים לצד הישנים, וההגדרות הפעילות שלמעלה ממשיכות לשרת את האחזור עד שתשנו אותן בעצמכם.';
$string['settings:embed_migration_provider_inherit'] = 'השתמש בספק שהוגדר למעלה';
$string['settings:embed_migration_target_apikey'] = 'מפתח API של ספק היעד';
$string['settings:embed_migration_target_apikey_desc'] = 'נדרש רק כאשר ספק היעד שונה מזה שהוגדר למעלה. ריק פירושו להשתמש במפתח ה-embedding הקיים.';
$string['settings:embed_migration_target_dimensions'] = 'רוחב ה-embedding של היעד';
$string['settings:embed_migration_target_dimensions_desc'] = 'רוחב הווקטור שיבוקש במהלך ההעברה. 0 פירושו הרוחב המקורי של המודל. Voyage מקבל 256, 512, 1024 ו-2048; רוחב שהמודל אינו מציע מושמט מן הבקשה במקום להישלח, מה שהיה נותן לכם בשקט את הרוחב המקורי במקום זה שביקשתם.';
$string['settings:embed_migration_target_model'] = 'מודל ה-embedding של היעד';
$string['settings:embed_migration_target_model_desc'] = 'שם המודל שאיתו יבוצע embedding במהלך ההעברה, לדוגמה <code>voyage-4-large</code>. ריק פירושו שלא הוגדרה העברה ודף אינדקס ה-RAG אינו מציע אף אחת.';
$string['settings:embed_migration_target_provider'] = 'ספק ה-embedding של היעד';
$string['settings:embed_migration_target_provider_desc'] = 'השאירו ריק כדי לבצע העברה בתוך הספק שכבר הוגדר למעלה.';
$string['settings:rerank_min_query_chars'] = 'דירוג מחדש: אורך שאילתה מינימלי';
$string['settings:rerank_min_query_chars_desc'] = 'דלגו על המדרג עבור שאילתות באורך הזה של תווים או קצרות ממנו. שאילתות קצרות הן בעלות אופי של מילות מפתח והמדרג כמעט אינו מוסיף דבר מעל דמיון קוסינוס על שתי מילים או שלוש. נמדד על מקבץ ה-fixtures של RAG: שער של 50 השיג 67.7% היזכרות מול 67.2% לדירוג תמיד-פעיל, בכשליש מהעלות. קבעו 0 כדי לדרג מחדש כל שאילתה. דילוגים על דירוג מחדש נרשמים ביומן ההודעות בצורת "[Rerank skipped: short_query]" כדי שתוכלו לאמת שהשער עובד.';
$string['settings:spend_export_key'] = 'מפתח ייצוא ההוצאות';
$string['settings:spend_export_key_desc'] = 'מפתח Bearer עבור נקודת הקצה החודשית לייצוא הוצאות ה-AI בכתובת <code>/local/ai_course_assistant/spend_export.php</code>, שלוח ההוצאות שולף ממנה פעם בחודש. השאירו ריק כדי לכבות את נקודת הקצה — היא תחזיר אז 404 לכל בקשה. המפתח מתקבל רק בכותרת <code>Authorization: Bearer</code>, לעולם לא ב-URL. צרו ערך ארוך ומקרי; כל מי שמחזיק בו יכול לקרוא את הוצאות ה-AI של האתר כולו. כל ייצוא מוצלח נרשם ביומן הביקורת של התוסף.';
