$string['prompt_playground:intro'] = 'הרכב את פרומפט המערכת ובדוק את התוצאה. שני מצבים: (1) הזן <strong>שאלת בדיקה</strong> כדי להריץ את מנגנון האחזור האמיתי ולראות בדיוק אילו מקטעים הוא בוחר עבור אותה שאלה, עם ציוני רלוונטיות — זו הדרך לאמת את בחירת המקטעים; או (2) הדבק קטעי טקסט משלך כדי לדמות מקטעים שאוחזרו. בחר קורס (ואופציונלית מזהה מודול-קורס של העמוד הנוכחי), ואז הרכב. תראה את המקטעים שנבחרו, את הפרומפט המדויק שהמודל היה מקבל, ואת פירוט הגדלים לפי סעיף. שום דבר אינו נשלח לספק AI כלשהו, וההרכבה מתבצעת בשמך (כמנהל), כך שאין חשיפה של נתוני לומדים.';
