$string['pricedrift:eol_horizon'] = 'אופק אזהרה לסוף חיים (ימים)';
$string['pricedrift:eol_horizon_desc'] = 'כמה זמן מראש מתחילים לדווח על פרישה מוכרזת של מודל. בדיקת הסחיפה עוקבת אחר מחיר; בלי זה שום דבר אינו עוקב אחר מחזור החיים, ופרישה אמיתית מגיעה כתקלת ייצור במקום כאזהרה — מודל ממשיך לעבוד וממשיך לחייב עד הרגע שבו הוא נפסק, ואז כל הקריאות נכשלות בבת אחת. ברירת מחדל 60 ימים, כי החלפת מודל בייצור היא מבחן השוואתי, שינוי הגדרות ופריסה, ולא עניין של אחר צהריים אחד. פרישה שמועדה כבר חלף מדווחת תמיד, יהיה הערך כאן אשר יהיה.';
$string['pricedrift:eol_surfaces'] = 'ממשקי API שאתר זה קורא להם';
$string['pricedrift:eol_surfaces_desc'] = 'מופרדים בפסיקים, לדוגמה <code>gemini-developer-api,openai-api</code>. התראה על פרישה מוכרזת נשלחת רק כאשר היא הוכרזה עבור אחד מהממשקים האלה; השאר עדיין מוצגים, מסומנים כלא שלכם. השאירו ריק כדי לקבל התראה על כל סוף חיים שנרשם. זה קיים בגלל כמעט-תקלה אמיתית: דווח ש-gemini-2.5-flash פורש ב-2026-10-16, מה שהיה נכון למחזור החיים של Vertex AI ולא ל-Gemini Developer API שהתוסף הזה קורא לו. זימון אחד לאירוע שלא היה מלמד אנשים להתעלם מהזימון הבא.';
