$string['settingspage:analytics_title'] = 'לוח ניתוח נתונים';
$string['settingspage:rag_explainer'] = 'RAG (יצירה מוגברת באחזור) מאנדקס את תוכן הקורס שלכם ומאחזר קטעים רלוונטיים כאשר סטודנטים שואלים שאלות, כך שה-AI יכול לתת תשובות המעוגנות בחומרים שלכם. נדרש מפתח API ל-embedding (מומלץ OpenAI). לאחר ההפעלה, השתמשו בדף ניהול ה-RAG כדי לאנדקס קורסים.';
$string['settingspage:realtime_explainer'] = 'מצב קולי בזמן אמת מאפשר שיחות דיבור חיות ודו-כיווניות בין סטודנטים לבין ה-AI באמצעות Realtime API של OpenAI. זה שונה מטקסט-לדיבור (TTS) רגיל, שרק מקריא בקול את תשובות ה-AI. הקול בזמן אמת דורש מפתח API נפרד ומחויב לפי דקת אודיו. לאחר ההפעלה הכללית, ניתן להפעיל או לכבות אותו לכל קורס בדף ההגדרות של אותו קורס.';
