$string['modelregistry:err_noeolsurface'] = 'לתאריך סוף חיים נדרש משטח ה-API שעבורו הוא הוכרז. הוצאה משימוש שהוכרזה עבור משטח אחד אינה חלה על משטח אחר, ותאריך שנרשם ללא משטח הוא הדרך שבה הודעת מחזור חיים על מודל שאינכם קוראים אליו הופכת לאזעקת תקלה כוזבת. השתמשו ב-\'any\' אם הוא חל בכל מקום.';
$string['modelregistry:field_eol_date'] = 'תאריך סוף חיים';
$string['modelregistry:field_eol_date_help'] = 'תאריך ההוצאה משימוש או הכיבוי שהוכרז, בכתיב YYYY-MM-DD. השאירו ריק כאשר לא הוכרז סוף חיים — ריק פירושו שלא הוכרז, לא שהמצב בטוח. התאריך נקרא כיום לוח ב-UTC ולא באזור הזמן שלכם, כדי שכל מי שקורא את השורה הזו יתכנן לאותו שבוע.';
$string['modelregistry:field_eol_surface'] = 'סוף החיים חל על';
$string['modelregistry:field_eol_surface_help'] = 'עבור איזה משטח API הוכרז התאריך: <code>gemini-developer-api</code>, <code>vertex-ai</code>, <code>openai-api</code>, <code>azure-openai</code>, <code>bedrock</code>, או <code>any</code> לכל המשטחים. נדרש בכל פעם שמוזן תאריך, וזו אינה בירוקרטיה: על gemini-2.5-flash דווח שייצא משימוש ב-2026-10-16, אך זה היה אירוע מחזור חיים של Vertex AI ולא של Gemini Developer API שהאתר הזה קורא אליו. בלי המשטח, תאריך כזה מעורר אזעקת תקלת ייצור על מודל שאינו הולך לשום מקום. רשמו תחת סחיפת מחירים את המשטחים שהאתר הזה באמת קורא אליהם, כדי שאלה שאינם שלכם יישארו ברמת מידע בלבד.';
