$string['modelregistry:status_retired'] = 'הוצא משימוש';
$string['privacy:metadata:bench'] = 'ריצות מדידה של ספקים: תוצאות השוואת המודלים שמנהל האתר הפיק. הנתון האישי היחיד הוא מזהה המנהל שהתחיל את הריצה. שורות אלה הן תצורת אתר ולא נתונים אישיים על לומד, ולכן הן אינן נכללות בייצוא נתונים ואינן נמחקות כאשר משתמש מבקש מחיקת נתונים.';
$string['privacy:metadata:bench:createdby'] = 'מנהל האתר שהתחיל את ריצת המדידה הזו. ריק כאשר הריצה הותחלה משורת הפקודה.';
$string['privacy:metadata:models'] = 'רשומות מרשם המודלים: עקיפות התמחור והיכולות לכל מודל שמנהל האתר מתחזק. הנתון האישי היחיד הוא מזהה המנהל ששמר את הרשומה לאחרונה. שורות אלה הן תצורת אתר ולא נתונים אישיים על לומד, ולכן הן אינן נכללות בייצוא נתונים ואינן נמחקות כאשר משתמש מבקש מחיקת נתונים.';
