$string['privacy:metadata:pricesrc'] = 'הגדרות הזנות תמחור: מחירוני הספקים שמנהל האתר הגדיר לתוסף לשלוף. הנתון האישי היחיד הוא מזהה המנהל שהוסיף את ההזנה. שורות אלה הן תצורת אתר ולא נתונים אישיים על לומד, ולכן הן אינן נכללות בייצוא נתונים ואינן נמחקות כאשר משתמש מבקש מחיקת נתונים.';
