$string['privacy:metadata:sbx_assign'] = 'מטלות מצגת Soapbox: המשימות שמורה מגדיר עבור קורס. הנתון האישי היחיד הוא מזהה איש הצוות שערך את המטלה לאחרונה. שורות אלה הן תצורת קורס ולא נתונים אישיים על לומד, ולכן הן אינן נכללות בייצוא נתונים ואינן נמחקות כאשר משתמש מבקש מחיקת נתונים, שכן מחיקה כזו הייתה משנה מטלה שלומדים אחרים עדיין עובדים לפיה.';
