$string['selftest:storage_intro'] = 'מעביר אובייקט בדיקה קטן הלוך ושוב דרך הדלי שהוגדר: העלאה, בדיקת גודל, הורדה עם השוואת בתים, מחיקה, ולבסוף בדיקה חוזרת שהוא אכן נעלם. כל שלב מדווח בנפרד, כי השלב שנכשל הוא האבחנה. הבדיקה מבצעת כתיבות ומחיקות אמיתיות בתוך תיקיית __selftest/ שבקידומת ההקלטות שהוגדרה, ולכן היא עוברת באותו מסלול שבו עוברת הקלטה של לומד.';
